class DataProcessor:
    def __init__(self, filter_func=None, transform_func=None):
        self._filter = filter_func
        self._transform = transform_func

    def process(self, data):
        result = []
        for item in data:
            if self._filter and not self._filter(item):
                continue
            transformed = self._transform(item) if self._transform else item
            result.append(transformed)
        return result

    @staticmethod
    def builder():
        return DataProcessorBuilder()


class DataProcessorBuilder:
    def __init__(self):
        self._filter = None
        self._transform = None

    def with_filter(self, filter_func):
        self._filter = filter_func
        return self

    def with_transform(self, transform_func):
        self._transform = transform_func
        return self

    def build(self):
        return DataProcessor(self._filter, self._transform)

