class DataProcessorBuilder:
    """Fluent builder for DataProcessor."""

    def __init__(self) -> None:
        self._adapter: DataAdapter = PassthroughAdapter()

    def with_filter(self, predicate: Callable[[Any], bool]) -> DataProcessorBuilder:
        self._adapter = PredicateAdapter(predicate, self._adapter)
        return self

    def with_transform(self, fn: Callable[[Any], Any]) -> DataProcessorBuilder:
        self._adapter = TransformAdapter(fn, self._adapter)
        return self

    def build(self) -> DataProcessor:
        return DataProcessor(self._adapter)

    def build(self) -> DataProcessor:
        return DataProcessor(self._adapter)


def from_config(config: dict[str, Any]) -> DataProcessor:
    """Build a processor from a config dict — drop-in replacement for the original."""
    builder = DataProcessor.builder()
    if config.get("transform"):
        builder.with_transform(config["transform"])
    if config.get("filter"):
        builder.with_filter(config["filter"])
